begin;
do $$ declare o uuid:='10000000-0000-4000-8000-000000000001'; site uuid:='10000000-0000-4000-8000-000000000002';
uc uuid:=gen_random_uuid(); ac uuid:=gen_random_uuid(); mc uuid:=gen_random_uuid();
um uuid:=gen_random_uuid(); am uuid:=gen_random_uuid(); mm uuid:=gen_random_uuid();
p uuid; p2 uuid; v uuid; n int; aud0 bigint; bu bigint; ba bigint; bp bigint; bt bigint; ba2 bigint; begin
select count(*) into bu from auth.users; select count(*) into ba from public.accounts; select count(*) into bp from public.patients; select count(*) into bt from public.care_team_assignments; select count(*) into ba2 from public.audit_events;
begin
insert into public.patients(org_id,source_key,first_name,last_name,synthetic) values(o,'moud-team-rollback-1','Fictional','Moud One',true) returning id into p;
insert into public.patients(org_id,source_key,first_name,last_name,synthetic) values(o,'moud-team-rollback-2','Fictional','Moud Two',true) returning id into p2;
insert into public.patient_site_enrollments(org_id,patient_id,site_id,starts_at,synthetic) values(o,p,site,now()-interval '1 day',true),(o,p2,site,now()-interval '1 day',true);
insert into auth.users(id,aud,role,email) values(uc,'authenticated','authenticated','moud-cc@example.test'),(um,'authenticated','authenticated','moud-cm@example.test');
insert into public.accounts(id,org_id,auth_user_id,kind,synthetic) values(ac,o,uc,'staff',true),(am,o,um,'staff',true);
insert into public.staff_members(id,org_id,account_id,source_key,name,synthetic) values(mc,o,ac,'moud-cc','Fictional Coordinator',true),(mm,o,am,'moud-cm','Fictional Care Manager',true);
insert into public.staff_role_assignments(org_id,staff_member_id,role,is_primary) values(o,mc,'clinical_coordinator',true),(o,mm,'ecm_provider',true);
insert into public.staff_site_assignments(org_id,staff_member_id,site_id,starts_at,synthetic) select o,x,site,now()-interval '1 day',true from unnest(array[mc,mm]) x;
perform set_config('request.jwt.claim.sub','',true);
perform set_config('request.jwt.claims',jsonb_build_object('sub',um,'role','authenticated')::text,true); perform app.attest_beta('en'); perform app.set_acting_role('ecm_provider');
set local role authenticated;
if (app.chart_entry(p)->>'ok')::boolean then raise exception 'cm_entry_before_assign'; end if;
reset role;
perform set_config('request.jwt.claims',jsonb_build_object('sub',uc,'role','authenticated')::text,true); perform app.attest_beta('en'); perform app.set_acting_role('clinical_coordinator');
begin perform public.moud_care_manager_assign(p,mc,'ep_1'); raise exception 'non_cm_target_accepted'; exception when others then if sqlerrm<>'active_care_manager_required' then raise; end if; end;
select count(*) into aud0 from public.audit_events where action_code like 'moud_care_manager%';
v:=public.moud_care_manager_assign(p,mm,'ep_1');
if (select count(*) from public.audit_events where action_code like 'moud_care_manager%')<>aud0+1 then raise exception 'one_audit_failed'; end if;
if not exists(select 1 from public.care_team_assignments where id=v and assignment_kind='care_manager' and ends_at is null and 'moud:ep_1'=any(source_refs)) then raise exception 'team_row_missing'; end if;
insert into public.care_team_assignments(org_id,patient_id,staff_member_id,role,assignment_kind,site_id,starts_at,synthetic) values(o,p2,mm,'care_manager','care_manager',site,now()-interval '1 hour',true);
v:=public.moud_care_manager_assign(p2,mm,'ep_2');
if (select count(*) from public.care_team_assignments where patient_id=p2 and staff_member_id=mm)<>1 then raise exception 'duplicate_membership'; end if;
perform set_config('request.jwt.claims',jsonb_build_object('sub',um,'role','authenticated')::text,true); perform app.set_acting_role('ecm_provider');
set local role authenticated;
if not (app.chart_entry(p)->>'ok')::boolean then raise exception 'assigned_entry_failed'; end if;
if app.phase2_chart_read(p,'screeners_sud') then raise exception 'part2_widened'; end if;
reset role;
perform set_config('request.jwt.claims',jsonb_build_object('sub',uc,'role','authenticated')::text,true); perform app.set_acting_role('clinical_coordinator');
n:=public.moud_care_manager_end(p2,'ep_2'); if n<>0 then raise exception 'other_membership_ended'; end if;
n:=public.moud_care_manager_end(p,'ep_1'); if n<>1 then raise exception 'episode_only_not_ended'; end if;
if not exists(select 1 from public.care_team_assignments where patient_id=p and staff_member_id=mm and ends_at is not null and cardinality(source_refs)=0) then raise exception 'episode_only_end_not_recorded'; end if;
if not exists(select 1 from public.care_team_assignments where patient_id=p2 and staff_member_id=mm and ends_at is null and 'coordinator'=any(source_refs)) then raise exception 'kept_row_changed'; end if;
perform set_config('request.jwt.claims',jsonb_build_object('sub',um,'role','authenticated')::text,true); perform app.set_acting_role('ecm_provider');
set local role authenticated;
if not (app.chart_entry(p2)->>'ok')::boolean then raise exception 'kept_membership_entry_failed'; end if;
reset role;
raise exception using errcode='ZX001',message='fixture_rollback';
exception when sqlstate 'ZX001' then null; end;
if (select count(*) from auth.users)<>bu or (select count(*) from public.accounts)<>ba or (select count(*) from public.patients)<>bp or (select count(*) from public.care_team_assignments)<>bt or (select count(*) from public.audit_events)<>ba2 then raise exception 'fixture_retained'; end if;
end $$;
rollback;